insert into rules (id, code, title, content, version, status, category_id, project_id, priority, tags, ai_platforms, updated_at) values ('d8fb3581-9e5e-47bb-a710-56292e8c80d0', 'IMG-001', '確定表示優先', '画像生成時に複数案が出た場合は、確定表示された案を優先して以降の生成に反映すること。', 'v1.3', 'active', '04e04f90-a7da-4827-b7ab-aac561c7c847', null, 'high', ARRAY['確定表示', '出力形式'], ARRAY['chatgpt', 'claude'], '2026-07-20T14:08:25.014Z');
