insert into rules (id, code, title, content, version, status, category_id, project_id, priority, tags, ai_platforms, updated_at) values ('e0a938c8-ba4d-4114-9167-6784b20d4de4', 'TXT-001', '原文維持の添削ルール', '文章添削では原文の意図・文体を維持し、必要最小限の修正に留めること。大幅な書き換えは提案として別途示す。', 'v1.3', 'active', 'c24673ca-f87a-4044-8158-da38cbf0e3dd', null, 'high', ARRAY['添削', '再発防止'], ARRAY['common'], '2026-07-20T13:28:25.014Z');
insert into rules (id, code, title, content, version, status, category_id, project_id, priority, tags, ai_platforms, updated_at) values ('73f089e9-5560-4b7d-b013-96ad0e852ee9', 'BUS-001', '業務質問は客観的に回答', '業務上の質問には主観的な意見を避け、根拠のある客観的な情報を優先して回答すること。', 'v1.5', 'stopped', 'e5d32cbd-2476-487a-b26b-ff6478fa309b', null, 'medium', ARRAY['トーン', '確認フロー'], ARRAY['claude'], '2026-07-20T13:28:25.014Z');
insert into rules (id, code, title, content, version, status, category_id, project_id, priority, tags, ai_platforms, updated_at) values ('85f6109c-f2b2-4a4e-8866-0188456e4b38', 'IMG-002', '比較画像生成時も適用', '複数画像を比較生成する場合も、確定表示優先ルール(IMG-001)を同様に適用すること。', 'v1.2', 'active', '04e04f90-a7da-4827-b7ab-aac561c7c847', null, 'low', ARRAY['画像品質'], ARRAY['chatgpt', 'gemini'], '2026-07-20T12:28:25.014Z');
insert into rules (id, code, title, content, version, status, category_id, project_id, priority, tags, ai_platforms, updated_at) values ('c46e2151-4a9d-43f8-8dc1-9d2cbf06ecf5', 'IMG-003', '生成前に構図案を提示', '画像生成前に簡単な構図案(ラフ)を提示し、ユーザーの承認を得てから本生成に進むこと。', 'v1.0', 'pending_approval', '04e04f90-a7da-4827-b7ab-aac561c7c847', null, 'medium', ARRAY['構図', '確認フロー'], ARRAY['chatgpt'], '2026-07-20T11:28:25.014Z');
insert into rules (id, code, title, content, version, status, category_id, project_id, priority, tags, ai_platforms, updated_at) values ('584c6d9b-88e9-4c30-8769-be2e45777246', 'TXT-002', '語尾は「です・ます」調で統一', '文章生成では語尾を「です・ます」調に統一し、常体と敬体が混在しないようにすること。', 'v1.1', 'active', 'c24673ca-f87a-4044-8158-da38cbf0e3dd', null, 'low', ARRAY['トーン', 'スタイル'], ARRAY['common'], '2026-07-20T10:28:25.014Z');
insert into rules (id, code, title, content, version, status, category_id, project_id, priority, tags, ai_platforms, updated_at) values ('b28605d7-aef4-4413-90bc-c65a8a8f8413', 'DOC-002', '見出しレベルの自動採番', 'ドキュメント生成時、見出しレベル(H1〜H3)に応じて章番号を自動採番すること。', 'v1.0', 'active', 'd3c502d6-2b5e-429d-acd2-e7de10cd7ffe', null, 'low', ARRAY['出力形式'], ARRAY['chatgpt', 'copilot'], '2026-07-20T09:28:25.014Z');
