insert into rules (id, code, title, content, version, status, category_id, project_id, priority, tags, ai_platforms, updated_at) values ('70693901-23e0-4bdd-913f-7899cad8dfa8', 'BUS-002', '社外秘情報は要約に含めない', '要約・議事録作成時、社外秘に分類される情報は要約本文に含めず、別途注意喚起すること。', 'v2.0', 'active', 'e5d32cbd-2476-487a-b26b-ff6478fa309b', null, 'high', ARRAY['セキュリティ', '要約'], ARRAY['common'], '2026-07-20T02:28:25.014Z');
insert into rules (id, code, title, content, version, status, category_id, project_id, priority, tags, ai_platforms, updated_at) values ('1df81076-c796-442e-84ad-a2db5a5ae18b', 'IMG-004', '顔のアップは高解像度で出力', '人物の顔がアップになる構図では、通常より高い解像度設定で出力すること。', 'v1.1', 'active', '04e04f90-a7da-4827-b7ab-aac561c7c847', null, 'medium', ARRAY['画像品質'], ARRAY['chatgpt', 'gemini'], '2026-07-19T14:28:25.014Z');
insert into rules (id, code, title, content, version, status, category_id, project_id, priority, tags, ai_platforms, updated_at) values ('8e191c55-d7c0-4767-81e5-95d2b8ce5b38', 'OTH-001', '個人的な相談では断定表現を避ける', '個人的な相談・雑談カテゴリでは断定的な言い切りを避け、「〜と考えられます」等の表現を用いること。', 'v1.2', 'active', '1952a412-7047-4e1e-86f1-1f1e3fee80c2', null, 'high', ARRAY['トーン', '確認フロー'], ARRAY['claude'], '2026-07-19T14:28:25.014Z');
insert into rules (id, code, title, content, version, status, category_id, project_id, priority, tags, ai_platforms, updated_at) values ('2ded6d51-73ba-400b-a3f0-dfff641617d5', 'DOC-003', '機密文書には透かしを挿入', '機密指定された文書をPDF出力する際は、ページ全体に「社外秘」等の透かしを挿入すること。', 'v1.0', 'draft', 'd3c502d6-2b5e-429d-acd2-e7de10cd7ffe', null, 'high', ARRAY['セキュリティ'], ARRAY['copilot'], '2026-07-18T14:28:25.014Z');
insert into rules (id, code, title, content, version, status, category_id, project_id, priority, tags, ai_platforms, updated_at) values ('9bf56ed1-fe1b-47cb-9456-0b06c3042c94', 'TXT-003', '専門用語には注釈を付与', '専門用語・業界用語を使用する場合は、初出箇所に簡単な注釈(*印+脚注)を付与すること。', 'v1.0', 'pending_approval', 'c24673ca-f87a-4044-8158-da38cbf0e3dd', null, 'low', ARRAY['スタイル'], ARRAY['common'], '2026-07-18T14:28:25.014Z');
