insert into rules (id, code, title, content, version, status, category_id, project_id, priority, tags, ai_platforms, updated_at) values ('a4e00036-f579-41b0-b483-494880309d36', 'OPS-002', '障害対応はエスカレーション手順に従う', 'システム障害を検知した場合は、定められたエスカレーション手順に従って報告・対応すること。', 'v1.6', 'active', 'a954af8a-932f-4ebb-a89e-f712afb763f3', null, 'high', ARRAY['運用', '確認フロー'], ARRAY['common'], '2026-07-17T14:28:25.014Z');
insert into rules (id, code, title, content, version, status, category_id, project_id, priority, tags, ai_platforms, updated_at) values ('8f0e9cc9-82b4-4251-854a-554ead9d9490', 'IMG-005', '著作権保護対象を含めない', '実在の著作物・キャラクター等、著作権保護対象となる要素を画像生成に含めないこと。', 'v1.1', 'active', '04e04f90-a7da-4827-b7ab-aac561c7c847', null, 'high', ARRAY['セキュリティ', '画像品質'], ARRAY['common'], '2026-07-16T14:28:25.014Z');
insert into rules (id, code, title, content, version, status, category_id, project_id, priority, tags, ai_platforms, updated_at) values ('ecd23514-ce80-459f-93a4-2a94038f5971', 'DOC-004', '表組みはMarkdown形式で出力', 'ドキュメント内の表組みはMarkdown形式(パイプ区切り)で出力し、後工程での変換を容易にすること。', 'v1.0', 'active', 'd3c502d6-2b5e-429d-acd2-e7de10cd7ffe', null, 'low', ARRAY['出力形式'], ARRAY['claude', 'copilot'], '2026-07-15T14:28:25.014Z');
insert into rules (id, code, title, content, version, status, category_id, project_id, priority, tags, ai_platforms, updated_at) values ('fd89d7d5-1e26-4ec4-8f34-ca37073dc1f0', 'TXT-004', '一文の長さを80文字以内に', '可読性向上のため、一文の長さは全角80文字以内を目安に区切ること。', 'v1.2', 'stopped', 'c24673ca-f87a-4044-8158-da38cbf0e3dd', null, 'low', ARRAY['スタイル'], ARRAY['chatgpt'], '2026-07-14T14:28:25.014Z');
insert into rules (id, code, title, content, version, status, category_id, project_id, priority, tags, ai_platforms, updated_at) values ('b62781b3-0ec0-4107-9b12-eeb9fc2f7092', 'BUS-004', 'メール文面は敬語レベルを統一', 'メール文面生成時は宛先の関係性に応じた敬語レベルを一文書内で統一すること。', 'v1.4', 'active', 'e5d32cbd-2476-487a-b26b-ff6478fa309b', null, 'medium', ARRAY['トーン'], ARRAY['common'], '2026-07-13T14:28:25.014Z');
insert into rules (id, code, title, content, version, status, category_id, project_id, priority, tags, ai_platforms, updated_at) values ('05716a00-7edf-41f3-96fa-8237af4c6492', 'OTH-002', '雑談時も敬体を維持', '雑談・カジュアルな会話であっても、基本的な敬体(です・ます調)は維持すること。', 'v1.0', 'active', '1952a412-7047-4e1e-86f1-1f1e3fee80c2', null, 'low', ARRAY['トーン'], ARRAY['gemini'], '2026-07-13T14:28:25.014Z');
